-- TransWave MVP: PostgreSQL foundation. Monetary amounts use numeric, never float.
create type job_status as enum ('DRAFT','OPEN','COMPLETED','READY_TO_INVOICE','CANCELLED');
create type invoice_status as enum ('DRAFT','PENDING_APPROVAL','APPROVED','ISSUED','PARTIALLY_PAID','PAID','VOID','CREDITED');
create type transport_mode as enum ('SEA','AIR','ROAD','MULTIMODAL');

create table companies (id uuid primary key, legal_name text not null, trade_name text, trn text, created_at timestamptz not null default now());
create table branches (id uuid primary key, company_id uuid not null references companies, code text not null, name text not null, emirate text not null, address text, trn text, active boolean not null default true, unique(company_id, code));
create table customers (id uuid primary key, customer_code text not null unique, company_name text not null, trn text, email text, phone text, payment_terms_days integer not null default 30 check(payment_terms_days >= 0), active boolean not null default true, created_at timestamptz not null default now());
create table jobs (id uuid primary key, branch_id uuid not null references branches, customer_id uuid not null references customers, job_number text not null unique, status job_status not null default 'DRAFT', transport_mode transport_mode not null, service_category text not null, salesperson_id uuid, opened_at date not null default current_date, created_at timestamptz not null default now());
create table shipments (id uuid primary key, job_id uuid not null unique references jobs on delete cascade, shipper_name text, consignee_name text, notify_party text, port_of_loading text, port_of_discharge text, place_of_delivery text, vessel text, voyage text, sailed_at date, terms text, commodity text);
create table shipment_documents (id uuid primary key, job_id uuid not null references jobs on delete cascade, document_type text not null check(document_type in ('HBL','MBL','HAWB','MAWB','CUSTOMS','OTHER')), document_number text not null, issue_date date, unique(job_id, document_type, document_number));
create table containers (id uuid primary key, job_id uuid not null references jobs on delete cascade, container_number text not null, size smallint check(size in (20,40,45)), container_type text, seal_number text, gross_weight_kg numeric(14,3), package_count integer, unique(job_id, container_number));
create table currencies (code char(3) primary key, name text not null, decimal_places smallint not null default 2);
create table ports (id uuid primary key, un_locode char(5) unique, name text not null, country_code char(2) not null, emirate text, active boolean not null default true, unique(name, country_code));
alter table shipments add column port_of_loading_id uuid references ports;
alter table shipments add column port_of_discharge_id uuid references ports;
create table tax_rates (id uuid primary key, code text not null unique, category text not null check(category in ('STANDARD','ZERO_RATED','EXEMPT','OUT_OF_SCOPE')), rate numeric(5,2) not null check(rate >= 0), effective_from date not null, effective_to date);
create table services (id uuid primary key, code text not null unique, name text not null, default_uom text, default_currency char(3) references currencies, default_tax_rate_id uuid references tax_rates, active boolean not null default true);
create table job_charges (id uuid primary key, job_id uuid not null references jobs on delete cascade, container_id uuid references containers, service_id uuid not null references services, description text not null, quantity numeric(14,3) not null check(quantity > 0), uom text, currency_code char(3) not null references currencies, exchange_rate numeric(18,8) not null check(exchange_rate > 0), unit_rate numeric(18,2) not null check(unit_rate >= 0), tax_rate_id uuid not null references tax_rates, amount_fc numeric(18,2) not null, amount_aed numeric(18,2) not null, billable boolean not null default true, invoiced_at timestamptz);
create table invoices (id uuid primary key, branch_id uuid not null references branches, customer_id uuid not null references customers, job_id uuid not null references jobs, invoice_number text not null unique, invoice_date date not null, due_date date not null, place_of_supply_emirate text not null, status invoice_status not null default 'DRAFT', subtotal_aed numeric(18,2) not null default 0, vat_amount_aed numeric(18,2) not null default 0, total_aed numeric(18,2) not null default 0, created_at timestamptz not null default now());
create table invoice_lines (id uuid primary key, invoice_id uuid not null references invoices on delete cascade, job_charge_id uuid references job_charges, container_id uuid references containers, line_no smallint not null, description text not null, quantity numeric(14,3) not null, uom text, currency_code char(3) not null references currencies, exchange_rate numeric(18,8) not null, unit_rate numeric(18,2) not null, taxable_amount_aed numeric(18,2) not null, tax_rate_id uuid not null references tax_rates, vat_amount_aed numeric(18,2) not null, total_amount_aed numeric(18,2) not null, unique(invoice_id, line_no));
create index jobs_customer_status_idx on jobs(customer_id, status);
create index job_charges_job_billable_idx on job_charges(job_id, billable) where invoiced_at is null;
create index invoices_customer_status_due_idx on invoices(customer_id, status, due_date);
